"use client";

import { Button } from "@/components/base/buttons/button";
import { useCountUp } from "@/hooks/use-count-up";
import { useEffect, useState } from "react";

export default function UseCountUpDemo() {
  const [target, setTarget] = useState(6400);
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  const display = useCountUp(target, reduced ? 1 : 600);
  return (
    <div className="flex w-full max-w-sm flex-col items-center gap-5 rounded-3xl border border-border-button-default bg-background-secondary-default p-6">
      <div className="text-center">
        <p className="text-body-medium text-text-secondary">Total subscribers</p>
        <p className="text-display-3-medium text-text-primary tabular-nums">
          {(reduced ? target : display).toLocaleString("en-US")}
        </p>
        <p className="text-body-2-regular text-text-tertiary">
          The value animates from its current position.
        </p>
      </div>
      <div className="flex gap-2">
        <Button variant="secondary" size="small" onClick={() => setTarget(6400)}>
          Reset
        </Button>
        <Button size="small" onClick={() => setTarget((value) => value + 1250)}>
          Add 1,250
        </Button>
      </div>
      <span className="sr-only" aria-live="polite">
        Target: {target.toLocaleString("en-US")} subscribers
      </span>
    </div>
  );
}

"use client";

import { Button } from "@/components/base/buttons/button";
import { useDismissOnOutsidePress } from "@/hooks/use-dismiss-on-outside-press";
import { useEffect, useRef, useState } from "react";

export default function UseDismissOnOutsidePressDemo() {
  const [open, setOpen] = useState(false);
  const [saved, setSaved] = useState(0);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  useDismissOnOutsidePress(open, () => setOpen(false), [triggerRef, panelRef]);
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [open]);
  return (
    <div className="flex min-h-[340px] w-full max-w-md flex-col items-center gap-4 rounded-3xl border border-border-button-default bg-background-secondary-default p-6">
      <p className="text-center text-body-regular text-text-secondary">
        Open the panel, interact inside it, then press anywhere outside to dismiss.
      </p>
      <div className="relative">
        <Button
          ref={triggerRef}
          variant="secondary"
          onClick={() => setOpen((value) => !value)}
          aria-expanded={open}
          aria-controls="outside-press-demo-panel"
        >
          {open ? "Close panel" : "Open panel"}
        </Button>
        {open && (
          <div
            ref={panelRef}
            id="outside-press-demo-panel"
            className="absolute top-full left-1/2 z-10 mt-2 flex w-64 -translate-x-1/2 flex-col gap-3 rounded-2xl border border-border-button-default bg-background-primary-default p-4 shadow-dropdown"
          >
            <p className="text-body-medium text-text-primary">Presses inside keep this open.</p>
            <p className="text-body-2-regular text-text-secondary" aria-live="polite">
              {saved} {saved === 1 ? "item" : "items"} saved
            </p>
            <Button size="small" onClick={() => setSaved((value) => value + 1)}>
              Save an item
            </Button>
          </div>
        )}
      </div>
      <button
        type="button"
        className="mt-auto rounded-lg px-3 py-1.5 text-body-2-medium text-text-secondary outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring"
      >
        Outside the panel
      </button>
    </div>
  );
}

